import{_ as t,o as i,c as s,a9 as n}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Run bundles","description":"","frontmatter":{},"headers":[],"relativePath":"reference/run-bundles.md","filePath":"reference/run-bundles.md","lastUpdated":null}'),a={name:"reference/run-bundles.md"};function r(o,e,d,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="Run-bundles" tabindex="-1">Run bundles <a class="header-anchor" href="#Run-bundles" aria-label="Permalink to &quot;Run bundles {#Run-bundles}&quot;">​</a></h1><p>A run bundle is a directory containing the measurements, diagnostics and context of one run. The CLI, Web Studio, VS Code and report tools read the same files. You can archive this directory as a CI artifact and inspect it later.</p><h2 id="What-does-/1-mean?" tabindex="-1">What does <code>/1</code> mean? <a class="header-anchor" href="#What-does-/1-mean?" aria-label="Permalink to &quot;What does \`/1\` mean? {#What-does-/1-mean?}&quot;">​</a></h2><p>Strings such as <code>perfchecker-run-bundle/1</code> and <code>perfchecker-agent-evidence/1</code> identify <strong>data formats</strong>. The part before the slash names the format; <code>1</code> is its schema version. It is not a URL, a directory suffix, a test count or the version of the PerfChecker package.</p><p>You see the identifier in the <code>schema_version</code> field of JSON output. For example, the beginning of a bundle&#39;s <code>manifest.json</code> contains this field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perfchecker-run-bundle/1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This is a field excerpt, not a complete manifest. Readers use it to decide whether they understand the file&#39;s structure. The format version changes when the contract requires a new reader; it does not change for every run.</p><p>For a suite plan, <code>perfchecker-suite-plan/1</code> can be read as <strong>“test plan, file format version 1.”</strong> The name identifies the kind of document. The integer identifies the rules for reading it: which fields exist and what they mean. Each kind of document has its own version number.</p><p>Why is there no <code>/2</code> or <code>/10</code> here? These documented formats still use their first version. A future incompatible change could introduce <code>/2</code>; further revisions could eventually reach <code>/10</code>. These are examples of possible future identifiers, not formats currently supported by PerfChecker. Bug fixes, new test runs and package releases do not automatically require a new file format.</p><p>For example, changing a field from a list of selected checks to a different structure could require a new format version so an older consumer does not silently interpret it incorrectly. An ordinary compatible change need not do so. If your integration encounters an unsupported version, report it explicitly instead of guessing that the file follows version 1.</p><p>You do not choose this integer when running a check. PerfChecker writes it in the output. It matters when developing an integration or migrating saved data; it is not a setting needed for the tutorials.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Identifier</th><th style="text-align:right;">Where you encounter it</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>perfchecker-suite-plan/1</code></td><td style="text-align:right;">Serialized plan returned by the planning API</td><td style="text-align:right;">Version 1 of the selected-check plan format</td></tr><tr><td style="text-align:right;"><code>perfchecker-testitem-run/1</code></td><td style="text-align:right;">JSON output from running selected test items</td><td style="text-align:right;">Version 1 of item measurements and outcomes</td></tr><tr><td style="text-align:right;"><code>perfchecker-run-bundle/1</code></td><td style="text-align:right;"><code>manifest.json</code> in an archived run</td><td style="text-align:right;">Version 1 of the complete run format</td></tr><tr><td style="text-align:right;"><code>perfchecker-agent-evidence/1</code></td><td style="text-align:right;">Dictionary returned by <code>agent_evidence(bundle)</code></td><td style="text-align:right;">Version 1 of a selected evidence summary for an advisor</td></tr><tr><td style="text-align:right;"><code>perfchecker-query/1</code></td><td style="text-align:right;">Serialized <code>PerformanceQuery</code></td><td style="text-align:right;">Version 1 of a reusable selection of results</td></tr><tr><td style="text-align:right;"><code>perfchecker-query-result/1</code></td><td style="text-align:right;">Serialized query output</td><td style="text-align:right;">Version 1 of the selected results</td></tr></tbody></table><p>For example, <code>agent_evidence(bundle)[&quot;schema_version&quot;]</code> returns the string <code>&quot;perfchecker-agent-evidence/1&quot;</code>. The evidence itself is in the other fields of that dictionary. See <a href="./../report-queries">Queries and documentation blocks</a> for selecting and displaying those results.</p><h2 id="Directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#Directory-layout" aria-label="Permalink to &quot;Directory layout {#Directory-layout}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run-directory/</span></span>
<span class="line"><span>├─ manifest.json</span></span>
<span class="line"><span>├─ measurement-definitions.json</span></span>
<span class="line"><span>├─ observations.jsonl</span></span>
<span class="line"><span>├─ diagnostics.jsonl</span></span>
<span class="line"><span>├─ artifacts.json</span></span>
<span class="line"><span>├─ integrity.json</span></span>
<span class="line"><span>└─ artifacts/</span></span></code></pre></div><h2 id="Contents" tabindex="-1">Contents <a class="header-anchor" href="#Contents" aria-label="Permalink to &quot;Contents {#Contents}&quot;">​</a></h2><ul><li><p><code>manifest.json</code>: run/attempt identity, state, suite plan, runtime, environment, capabilities, timestamps, reuse key, and warnings;</p></li><li><p><code>measurement-definitions.json</code>: versioned meaning, unit, preference, method, scope, and comparability of each metric;</p></li><li><p><code>observations.jsonl</code>: numeric or categorical evidence with comparison keys and attributes;</p></li><li><p><code>diagnostics.jsonl</code>: compatibility failures, collector warnings, attribution findings, and other non-observation evidence;</p></li><li><p><code>artifacts.json</code>: metadata for profiles, plots, logs, and provider artifacts;</p></li><li><p><code>integrity.json</code>: SHA-256 and byte length for every immutable protocol file.</p></li></ul><p>Large files live under <code>artifacts/</code>; metadata should carry media type, sensitivity, and provenance. Integrity covers the protocol documents, while artifact-specific digests belong in artifact records.</p><h2 id="Julia-API" tabindex="-1">Julia API <a class="header-anchor" href="#Julia-API" aria-label="Permalink to &quot;Julia API {#Julia-API}&quot;">​</a></h2><p>Use <code>bundle_directory</code> from the <a href="/PerfChecker/dev/interfaces/visualization#Build-a-plot-from-a-saved-run">saved Bibliography plot example</a>, or the path to any existing suite bundle containing <code>manifest.json</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bundle </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_run_bundle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle_directory)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">verify_run_bundle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle_directory; require_integrity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bundle_passed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bundle_dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">list_run_bundles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/results&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; recursive </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>write_run_bundle</code> writes to a temporary sibling and atomically renames the directory. It refuses to overwrite an existing destination. <code>migrate_run_bundle</code> rewrites supported legacy data into a new destination rather than mutating the source in place.</p><h2 id="Identity-and-reuse" tabindex="-1">Identity and reuse <a class="header-anchor" href="#Identity-and-reuse" aria-label="Permalink to &quot;Identity and reuse {#Identity-and-reuse}&quot;">​</a></h2><p><code>run_id</code> is the logical experiment; <code>attempt_id</code> identifies one physical attempt. A content-derived <code>reuse_key</code> describes the normalized plan, runtime, and measurement definitions. Reused evidence must remain labelled as reused and must never silently impersonate a fresh run.</p><p>Consumers must verify integrity, schema version, completion state, diagnostic severity, measurement-definition identity, and semantic outcome before making a regression decision.</p>`,25)])])}const g=t(a,[["render",r]]);export{u as __pageData,g as default};
